    @classmethod
    def _matches(
        cls,
        item: Mapping[str, Any],
        expected: Mapping[str, Any],
        *,
        date_keys: set[str] | None = None,
    ) -> bool:
        for key, value in expected.items():
            actual = item.get(key)
            if date_keys and key in date_keys:
                if cls._normalize_date(actual) != cls._normalize_date(value):
                    return False
            elif isinstance(value, (int, float)) and not isinstance(value, bool):
                try:
                    if round(float(actual), 6) != round(float(value), 6):
                        return False
                except (TypeError, ValueError):
                    return False
            elif str(actual if actual is not None else "") != str(value):
                return False
        return True

    @staticmethod
    def _normalize_date(value: Any) -> str:
        raw = str(value or "").strip()
        parts = raw.split("T", 1)[0].split("-")
        if len(parts) != 3:
            return raw
        try:
            return date(int(parts[0]), int(parts[1]), int(parts[2])).isoformat()
        except ValueError:
            return raw

    @staticmethod
    def _is_after(value: str, baseline: str) -> bool:
        if not value or not baseline:
            return False
        try:
            return datetime.fromisoformat(value.replace("Z", "+00:00")) > datetime.fromisoformat(
                baseline.replace("Z", "+00:00")
            )
        except ValueError:
            return value > baseline

    @staticmethod
    def _summary(item: Mapping[str, Any], keys: tuple[str, ...]) -> dict[str, Any]:
        return {key: item.get(key) for key in keys}

    @staticmethod
    def _summarize_ride(item: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "id": item.get("id"),
            "driverId": item.get("driverId"),
            "status": item.get("status"),
            "createdAt": item.get("createdAt"),
            "acceptedAt": item.get("acceptedAt"),
            "timeline": item.get("timeline"),
        }


